CREATE OR REPLACE FUNCTION calc_effective_leverage(
    p_levscale TEXT,
    p_position_value NUMERIC,
    p_balance NUMERIC
) RETURNS NUMERIC AS $$
BEGIN
    -- Effective leverage = position value / balance
    -- This represents how leveraged the position is relative to the account balance/collateral
    IF p_balance IS NULL OR p_balance = 0 THEN
        RETURN NULL;
    END IF;

    RETURN p_position_value / p_balance;
END;
$$ LANGUAGE plpgsql;

